import pathlib,json,hashlib,subprocess,time,os,sys
npm=pathlib.Path('/home/qian-qi/work/hepta-rea-reference-20261103/install/node_modules/rea-agents')
out=pathlib.Path('/home/qian-qi/work/hepta-rea-contracts-20261104-r4-evidence/apk/evidence-file-access-reference-r1')
out.mkdir()
path=out/'permission.json'
path.write_bytes(b'{}')
path.chmod(0)
request=dict(npm=str(npm),cases=[dict(name='permission',path=str(path)),dict(name='path-limit',path=str(out/('x'*256)))])
(out/'request.json').write_text(json.dumps(request,indent=2)+'\n')
runner=r"""
import fs from 'node:fs/promises';
import {pathToFileURL} from 'node:url';
const out=process.argv[2];
const request=JSON.parse(await fs.readFile(out+'/request.json','utf8'));
const {readJsonFile}=await import(pathToFileURL(request.npm+'/dist/application/JsonFiles.js'));
const {projectAnalysisError}=await import(pathToFileURL(request.npm+'/dist/domain/analysisErrorProjection.js'));
const cases=[];
for(const row of request.cases){
 const result=await readJsonFile(row.path,undefined,undefined,'inspect_analysis_view');
 cases.push({...row,expected:result.ok?{ok:true}:{ok:false,typed_error:Object.fromEntries(Object.entries(result.error).filter(([k])=>k!=='cause')),projected:projectAnalysisError(result.error)}});
}
await fs.writeFile(out+'/goldens.json',JSON.stringify({format:'hepta.evidence-file-access-original.v1',node:process.version,uid:process.getuid(),cases},null,2)+'\n');
console.log(JSON.stringify(cases.map(c=>({name:c.name,expected:c.expected}))));
"""
(out/'runner.mjs').write_text(runner)
start=time.monotonic()
try:
 with (out/'stdout.log').open('wb') as stdout,(out/'stderr.log').open('wb') as stderr:
  process=subprocess.run(['node',str(out/'runner.mjs'),str(out)],cwd=out,stdout=stdout,stderr=stderr,timeout=90)
finally:path.chmod(0o600)
assert process.returncode==0,process.returncode
data=(out/'goldens.json').read_bytes()
cases=json.loads(data)['cases']
assert [c['expected']['typed_error']['reason'] for c in cases]==['io','path-limit']
summary=dict(passed=True,exit_code=0,seconds=time.monotonic()-start,budget_seconds=90,goldens_sha256=hashlib.sha256(data).hexdigest(),goldens_bytes=len(data),uid=os.getuid(),frozen_npm_tarball_sha256='8d542ec76a9cb350584b60a6c9c088706ff812d5bb5b094c20c95b6dc25698bb')
(out/'qualification.json').write_text(json.dumps(summary,indent=2)+'\n')
print((out/'stdout.log').read_text(),flush=True)
print(json.dumps(summary),flush=True)
